require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/JalaliDate.php';require_once __DIR__.'/../services/WorkPlannerService.php';Auth::requireLogin();$user=Auth::user();$userId=(int)$user['id'];$pageTitle='برنامه کاری من';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/employee/work-planner.php');}$action=(string)($_POST['action']??'');try{if($action==='personal'){$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان وظیفه الزامی است.');$due=JalaliDate::toGregorian($_POST['due_date']??'')?:date('Y-m-d');Database::execute('INSERT INTO work_planner_tasks(user_id,employee_id,assigned_by,title,description,task_type,priority,status,start_date,due_date,progress_percent,is_locked,is_personal,is_visible_on_dashboard,created_at,updated_at) VALUES (?,?,?,?,?,"custom",?,"todo",CURDATE(),?,0,0,1,1,NOW(),NOW())',[$userId,$userId,$userId,$title,trim((string)($_POST['description']??'')),in_array($_POST['priority']??'',['low','normal','high','urgent'],true)?$_POST['priority']:'normal',$due]);$id=(int)Database::lastInsertId();WorkPlannerService::logTaskAction($id,$userId,'created',null,['personal'=>true]);flash('وظیفه شخصی ایجاد شد.');}elseif($action==='status'){if(!WorkPlannerService::updateTaskStatus((int)$_POST['task_id'],(string)$_POST['status'],$userId))throw new InvalidArgumentException('تغییر وضعیت مجاز نیست.');flash('وضعیت بروزرسانی شد.');}elseif($action==='progress'){if(!WorkPlannerService::updateTaskProgress((int)$_POST['task_id'],(int)$_POST['progress_percent'],$userId))throw new InvalidArgumentException('ثبت پیشرفت مجاز نیست.');flash('پیشرفت ثبت شد.');}elseif($action==='comment'){$taskId=(int)$_POST['task_id'];$text=trim((string)($_POST['comment_text']??''));if($text===''||!WorkPlannerService::canUserAccessTask($userId,$taskId))throw new InvalidArgumentException('یادداشت معتبر نیست.');Database::execute('INSERT INTO work_planner_comments(task_id,user_id,comment_text,created_at,updated_at) VALUES (?,?,?,NOW(),NOW())',[$taskId,$userId,$text]);WorkPlannerService::logTaskAction($taskId,$userId,'comment_added',null,null,$text);flash('یادداشت ثبت شد.');}elseif($action==='preferences'){$views=['list','kanban','calendar','daily','weekly'];$groups=['status','priority','due_date','role','module','none'];$sorts=['priority','due_date','created_at','manual'];$styles=['field_sales','supervisor','sales_manager','warehouse_operation','finance_admin','it_planning','executive','general_employee'];$data=[in_array($_POST['default_view']??'',$views,true)?$_POST['default_view']:'list',isset($_POST['dashboard_widget_enabled'])?1:0,isset($_POST['show_in_progress_first'])?1:0,isset($_POST['show_overdue_tasks'])?1:0,isset($_POST['show_today_tasks'])?1:0,isset($_POST['show_completed_tasks'])?1:0,in_array($_POST['preferred_grouping']??'',$groups,true)?$_POST['preferred_grouping']:'status',in_array($_POST['preferred_sorting']??'',$sorts,true)?$_POST['preferred_sorting']:'priority',in_array($_POST['work_style']??'',$styles,true)?$_POST['work_style']:WorkPlannerService::inferWorkStyle($userId),isset($_POST['compact_mode'])?1:0];Database::execute('INSERT INTO work_planner_user_preferences(user_id,default_view,dashboard_widget_enabled,show_in_progress_first,show_overdue_tasks,show_today_tasks,show_completed_tasks,preferred_grouping,preferred_sorting,work_style,compact_mode,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE default_view=VALUES(default_view),dashboard_widget_enabled=VALUES(dashboard_widget_enabled),show_in_progress_first=VALUES(show_in_progress_first),show_overdue_tasks=VALUES(show_overdue_tasks),show_today_tasks=VALUES(show_today_tasks),show_completed_tasks=VALUES(show_completed_tasks),preferred_grouping=VALUES(preferred_grouping),preferred_sorting=VALUES(preferred_sorting),work_style=VALUES(work_style),compact_mode=VALUES(compact_mode),updated_at=NOW()',[$userId,...$data]);flash('تنظیمات پلنر ذخیره شد.');}}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Employee planner: '.$e->getMessage());flash('عملیات پلنر انجام نشد. لطفاً دوباره تلاش کنید.','danger');}redirect('/employee/work-planner.php');}
$prefs=WorkPlannerService::getUserPlannerPreferences($userId);$where=['user_id=?'];$params=[$userId];if(!(int)$prefs['show_completed_tasks'])$where[]='status NOT IN("done","cancelled")';$tasks=Database::fetchAll('SELECT * FROM work_planner_tasks WHERE '.implode(' AND ',$where).' ORDER BY CASE WHEN due_date<CURDATE() AND status NOT IN("done","cancelled") THEN 0 WHEN status="in_progress" THEN 1 WHEN priority="urgent" THEN 2 ELSE 3 END,due_date,manual_sort_order,id DESC',$params);$today=array_filter($tasks,fn($t)=>$t['due_date']===date('Y-m-d'));$overdue=array_filter($tasks,fn($t)=>$t['due_date']&&$t['due_date']<date('Y-m-d')&&!in_array($t['status'],['done','cancelled'],true));$doing=array_filter($tasks,fn($t)=>$t['status']==='in_progress');require __DIR__.'/../views/partials/admin-header.php';?>
