><span>سبک کاری</span><select name="work_style"><?php foreach(['field_sales','supervisor','sales_manager','warehouse_operation','finance_admin','it_planning','executive','general_employee'] as $style):?><option value="<?=e($style)?>" <?=$prefs['work_style']===$style?'selected':''?>><?=e($style)?></option><?php endforeach?></select></label><label class="checkbox-item"><input type="checkbox" name="dashboard_widget_enabled" <?=(int)$prefs['dashboard_widget_enabled']?'checked':''?>> ویجت داشبورد</label><label class="checkbox-item"><input type="checkbox" name="show_in_progress_first" <?=(int)$prefs['show_in_progress_first']?'checked':''?>> در حال انجام در ابتدا</label><label class="checkbox-item"><input type="checkbox" name="show_overdue_tasks" <?=(int)$prefs['show_overdue_tasks']?'checked':''?>> نمایش عقب‌افتاده</label><label class="checkbox-item"><input type="checkbox" name="show_today_tasks" <?=(int)$prefs['show_today_tasks']?'checked':''?>> نمایش امروز</label><label class="checkbox-item"><input type="checkbox" name="show_completed_tasks" <?=(int)$prefs['show_completed_tasks']?'checked':''?>> نمایش تکمیل‌شده</label><label class="checkbox-item"><input type="checkbox" name="compact_mode" <?=(int)$prefs['compact_mode']?'checked':''?>> حالت فشرده</label></div><button class="btn">ذخیره تنظیمات</button></form></section></div>
<section class="planner-board planner-view-<?=e($prefs['default_view'])?>"><?php foreach($tasks as $task):?><article class="card planner-task-card"><header><div><span class="badge"><?=e($task['priority'])?></span><?php if((int)$task['is_locked']):?><span class="badge">اجباری</span><?php endif?></div><small><?=e($task['due_date']?format_jalali_date($task['due_date']):'-')?></small></header><h2><?=e($task['title'])?></h2><p><?=e($task['description']?:'بدون توضیحات')?></p><div class="planner-progress"><span style="width:<?=e((string)max(0,min(100,(int)$task['progress_percent'])))?>%"></span></div><small><?=e((string)$task['progress_percent'])?>٪ — <?=e($task['status'])?></small><div class="form-actions"><?php if($task['status']==='todo'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><input type="hidden" name="status" value="in_progress"><button class="btn btn-small">شروع انجام</button></form><?php endif?><?php if(!in_array($task['status'],['done','cancelled'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><input type="hidden" name="status" value="done"><button class="btn btn-small btn-primary">تکمیل</button></form><?php endif?></div><details><summary>پیشرفت و یادداشت</summary><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="progress"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><input type="number" min="0" max="100" name="progress_percent" value="<?=e((string)$task['progress_percent'])?>"><button class="btn btn-small">ثبت</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="comment"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><textarea name="comment_text" required></textarea><button class="btn btn-small">افزودن یادداشت</button></form></details></article><?php endforeach?><?php if(!$tasks):?><section class="card"><h2>برای امروز وظیفه فعالی ثبت نشده است.</h2></section><?php endif?></section>
